module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output reg [WIDTH-1:0]	rdata
);


reg [WIDTH-1:0] RAM_MEM[0:DEPTH-1];
reg [3:0] waddr_bin, raddr_bin;
reg [3:0] wptr, rptr, wptr_buff, rptr_buff, wptr_syn, rptr_syn;

function [3:0] bin_to_gray(input [3:0] bin);
    bin_to_gray = bin ^ (bin >> 1);
endfunction

function [3:0] gray_to_bin(input [3:0] gray);
    integer i;
    gray_to_bin = gray;
    for(i=0;i<=3;i=i+1) begin
        gray_to_bin[i] = gray_to_bin[i] ^ gray_to_bin[i+1];
    end
endfunction

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        wptr <= 0;
    end else begin
        if (winc && !wfull) begin
            RAM_MEM[waddr_bin] <= wdata;
            waddr_bin <= waddr_bin + 1;
            wptr <= bin_to_gray(waddr_bin + 1);
        end else begin
            waddr_bin <= waddr_bin;
            wptr <= wptr;
        end
    end
end

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_syn <= 0;
        rptr_buff <= 0;
    end else begin
        rptr_syn <= rptr;
        rptr_buff <= rptr_syn;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_syn <= 0;
        wptr_buff <= 0;
    end else begin
        wptr_syn <= wptr;
        wptr_buff <= wptr_syn;
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        rptr <= 0;
    end else begin
        if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
            rptr <= bin_to_gray(raddr_bin + 1);
        end else begin
            raddr_bin <= raddr_bin;
            rptr <= rptr;
        end
    end
end

assign wfull = (wptr == {~rptr_syn[3], rptr_syn[2:0]});
assign rempty = (rptr == wptr_buff);
endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
